-- Natural Earth 1:110m Admin 0 - Countries, public domain.
-- https://www.naturalearthdata.com/downloads/110m-cultural-vectors/110m-admin-0-countries/
-- Generated from the ne_110m_admin_0_countries table of natural_earth_vector.sqlite.
-- The geom_3857 column has the geometries clipped to the EPSG:3857 latitude bounds for mvt layers.

CREATE SCHEMA IF NOT EXISTS naturalearth;

CREATE TABLE naturalearth.countries (
  id INTEGER PRIMARY KEY,
  name TEXT,
  name_long TEXT,
  iso_a3 TEXT,
  continent TEXT,
  subregion TEXT,
  pop_est BIGINT,
  mapcolor7 INTEGER,
  geom_4326 GEOMETRY(MultiPolygon, 4326),
  geom_3857 GEOMETRY(MultiPolygon, 3857)
);


UPDATE naturalearth.countries SET geom_3857 = ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Transform(
  ST_Intersection(geom_4326, ST_MakeEnvelope(-180, -85.06, 180, 85.06, 4326)),
  3857)), 3));

CREATE INDEX countries_geom_4326_idx ON naturalearth.countries USING GIST (geom_4326);
CREATE INDEX countries_geom_3857_idx ON naturalearth.countries USING GIST (geom_3857);
